package blockbranch.realistic;
import net.minecraft.core.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.levelgen.structure.BoundingBox;import it.unimi.dsi.fastutil.longs.*;
/** Every collidable component must reach unchanged terrain or retained vegetation outside the complete construction bounds. */
final class ReimaginedGrounding {
 static int verify(ServerLevel level,BoundingBox box,java.util.Set<Long> nativeFloating,java.util.Map<Long,java.util.List<Long>> nativeArchJoins){var blocks=new LongOpenHashSet();for(var p:BlockPos.betweenClosed(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ()))if(!level.getBlockState(p).getCollisionShape(level,p).isEmpty())blocks.add(p.asLong());int count=blocks.size();var queue=new LongArrayFIFOQueue();while(!blocks.isEmpty()){long first=blocks.iterator().nextLong();blocks.remove(first);queue.enqueue(first);boolean grounded=false;var sample=new java.util.ArrayList<Object>();int component=0;while(!queue.isEmpty()){var p=BlockPos.of(queue.dequeueLong());component++;if(nativeFloating.contains(p.asLong())&&level.getBlockState(p).is(net.minecraft.world.level.block.Blocks.LILY_PAD)&&level.getBlockState(p).canSurvive(level,p)&&level.getFluidState(p.below()).is(net.minecraft.tags.FluidTags.WATER))grounded=true;if(sample.size()<128)sample.add(java.util.Map.of("position",p.toShortString(),"state",level.getBlockState(p).toString(),"neighbors",java.util.Arrays.stream(Direction.values()).map(d->d+"="+level.getBlockState(p.relative(d))).toList()));for(long neighbor:nativeArchJoins.getOrDefault(p.asLong(),java.util.List.of()))if(blocks.remove(neighbor))queue.enqueue(neighbor);for(var d:Direction.values()){var next=p.relative(d);if(blocks.remove(next.asLong()))queue.enqueue(next.asLong());else if(!box.isInside(next)&&!level.getBlockState(next).getCollisionShape(level,next).isEmpty())grounded=true;}}if(!grounded){try{java.nio.file.Files.writeString(java.nio.file.Path.of("unsupported-component.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(java.util.Map.of("size",component,"sample",sample)));}catch(Exception ignored){}throw new AssertionError("Unsupported complete construction component "+BlockPos.of(first)+" size="+component+" state="+level.getBlockState(BlockPos.of(first)));}}return count;}
}
